import numpy as np
from collections import Counter

def solve(I, order_key, slide_mode):
    I=np.array(I); H,W=I.shape
    bg=Counter(I.ravel()).most_common(1)[0][0]
    C=comps2(I,bg)
    objs=[set(map(tuple,c)) for c in C] if slide_mode=='min' else sorted(C,key=len)
    # absorb strays into adjacent or nearest comp first
    objs=[o for o in objs if len(o)>=2]
    for cc in [c for c in C if len(c)==1]:
        s=next(iter(cc))
        best=min(objs,key=lambda o:min(abs(s[0]-r)+abs(s[1]-c) for r,c in o))
        best.add(s)
    anchor=min(objs,key=lambda o:min(c for r,c in o))
    rest=[o for o in objs if o is not anchor]
    rest_sorted=sorted(rest,key=order_key)
    O=[[bg]*W for _ in range(H)]
    placed=set()
    def put(o,color=None):
        for r,c in o:
            assert (r,c) not in placed
            O[r][c]=color
            placed.add((r,c))
    def occupied(r,c): return (r,c) in placed
    def free(cells):
        return not any(occupied(r,c) for r,c in cells)
    def adj(o):
        return any(occupied(r+dr,c+dc) for r,c in o for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)))
    # candidate translations: those where object becomes adjacent without overlap
    def get_moves(o):
        mr=min(r for r,c in o); mc=min(c for r,c in o)
        rel=[(r-mr,c-mc) for r,c in o]
        res=[]
        # enumerate small window of deltas: dc in [-W..W], dr in [-H..H]; filter adjacency&no-overlap
        for dr in range(-H,H+1):
            for dc in range(-W,W+1):
                cells=[(r+dr,c+dc) for r,c in rel]
                if free(cells) and adj(cells): res.append((cells,(dr,dc)))
        return res
    def manh(d): return abs(d[0])+abs(d[1])
    for o in rest_sorted:
        moves=get_moves(o)
        if slide_mode=='min':
            best=min(moves,key=lambda m:(manh(m[1]),m[1][0],m[1][1]))
        elif slide_mode=='diag':
            def keyf(m):
                k=10*( -m[1][0]-m[1][1]) - manh(m[1])  # prefer diagonal up-left contact then min dist
                return (k, -m[1][0], -m[1][1])
            best=min(moves,key=keyf)
        else:
            best=min(moves,key=lambda m:m[1][0]+m[1][1])
        col=max(set(int(I[r,c]) for r,c in o),key=list(o).count)
        put(best[0],col)
    return O

