from collections import Counter
def comps2(M,bg):
    M=np.array(M); H,W=M.shape; seen=set(); res=[]
    for r in range(H):
        for c in range(W):
            if M[r,c]!=bg and (r,c) not in seen:
                st=[(r,c)]; comp=set()
                while st:
                    p=st.pop()
                    if p in comp: continue
                    comp.add(p)
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        q=(p[0]+dr,p[1]+dc)
                        if 0<=q[0]<H and 0<=q[1]<W and M[q]!=bg and q not in comp: st.append(q)
                seen|=comp; res.append(comp)
    return res
