    bg=Counter(I.ravel()).most_common(1)[0][0]
    Cs=comps_of(I,bg)
    objs=[sorted(c) for c in Cs if len(c)>=2]; singles=[next(iter(c)) for c in Cs if len(c)==1]
    anch=min(objs,key=lambda o:min(x for y,x in o))   # leftmost object = anchor
    ext=[]
    for o in objs:
        cols=[int(I[r,c]) for r,c in o]
        ext.append((o,Counter(cols).most_common(1)[0][0]))
    def dist(o,P): return min(abs(r-y)+abs(c-x) for r,c in o for y,x in P)
    O=np.full((H,W),int(bg)); Pset=set()
    ak=ext.index([e for e in ext if e[0]==anch][0])
    for (r,c) in ext[ak][0]: O[r,c]=ext[ak][1]
    Pset=set(ext[ak][0])
    for k in range(len(ext)):
        if k==ak: continue
        o,col=ext[k]
        best=None
        for dr in range(-H,H):
            for dc in range(-W,W):
                pos=[(r+dr,c+dc) for r,c in o]
                if any(not(0<=r<H and 0<=c<W) for r,c in pos): continue
                tp={tuple(p) for p in pos}
                if any(p in Pset for p in tp): continue
                touch=any(((r+1,c) in Pset or (r-1,c) in Pset or (r,c+1) in Pset or (r,c-1) in Pset) for r,c in pos)
                cost=abs(dr)+abs(dc)
                if touch and (best is None or cost<best[0]): best=(cost,dr,dc,pos)
        if best:
            for (r,c) in best[3]: O[r,c]=col
            Pset|={(r,c) for r,c in best[3]}
    rs=[r for r,_ in Pset]; cs=[c for _,c in Pset]
    return O[min(rs):max(rs)+1,min(cs):max(cs)+1]
Ii=np.array(G['Demo pair 1 input']); Oo=np.array(G['Demo pair 1 output'])
P=solve(Ii)
print('pred'); [print(''.join(map(str,row))) for row in P]
print('want'); [print(''.join(map(str,row))) for row in Oo]

