import numpy as np
from collections import Counter
def comps_of(I,bg):
    H,W=I.shape; seen=np.zeros_like(I,bool); out=[]
    for r in range(H):
        for c in range(W):
            if I[r,c]!=bg and not seen[r,c]:
                st=[(r,c)]; seen[r,c]=True; cc=set()
                while st:
                    y,x=st.pop(); cc.add((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and I[ny,nx]!=bg and not seen[ny,nx]:
                            seen[ny,nx]=True; st.append((ny,nx))
                out.append(sorted(cc))
    return out
def comps(I,bg):
    cs=comps_of(np.array(I),bg); objs=[sorted(c) for c in cs if len(c)>=2]
    singles=[next(iter(c)) for c in cs if len(c)==1]
    return objs,singles
