    objs,singles=comps(Ii,bg)
    print(f'--- d{i}: bg={bg} objs={[(len(o),min(x for y,x in o),max(y for y,x in o),min(y for y,x in o),tuple(sorted(set(Ii[y,x] for y,x in o)))) for o in objs]}')
