import numpy as np, os, re
from collections import Counter
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))

Ii=np.array(G['Demo pair 1 input']); Oo=np.array(G['Demo pair 1 output'])
for i in [2,3,4,5,6]:
    I=np.array(G[f'Demo pair {i} input']); O=np.array(G[f'Demo pair {i} output'])
    bg=Counter(I.ravel()).most_common(1)[0][0]
    objs,singles=comps(I,bg)
    anch=min(objs,key=lambda o:min(x for y,x in o))
    print(f'--- d{i}: anchor col={min(c for r,c in anch)}')
    # check whether all other comps translated to touch anchor orthogonally
    Pset=set(anch); pred=I.copy()
    for o in sorted(objs,key=lambda o: min(c for r,c in o),reverse=True):
        if id(o)==id(anch): continue
        best=None
        for dr in range(-len(I),len(I)):
            for dc in range(-len(I[0]),len(I[0])):
                pos=[(r+dr,c+dc) for r,c in o]
                if any(not(0<=r<len(I) and 0<=c<len(I[0])) for r,c in pos): continue
                tp={p for p in pos}
                if tp & set(Pset): continue
                touch=any(((r+1,c) in Pset or (r-1,c) in Pset or (r,c+1) in Pset or (r,c-1) in Pset) for r,c in pos)
                cost=(not touch)+abs(dr)+abs(dc)
                if best is None or cost<best[0]: best=(cost,dr,dc,pos)
        if best:
            for (r,c) in best[3]: pred[r,c]=o==anch and bg
            Pset|={p for p in best[3]}
    show((I!=O).astype(int),'diff d1')

